package main
import("crypto/sha256";"debug/elf";"debug/gosym";"debug/buildinfo";"encoding/hex";"encoding/json";"fmt";"os";"io";"strings")
func main(){p:=os.Args[1];f,e:=elf.Open(p);if e!=nil{panic(e)};defer f.Close();s:=f.Section(".gopclntab");if s==nil{panic("Go function table unavailable")};b,e:=s.Data();if e!=nil{panic(e)};tx:=f.Section(".text");if tx==nil{panic("text unavailable")};t,e:=gosym.NewTable(nil,gosym.NewLineTable(b,tx.Addr));if e!=nil{panic(e)};if len(t.Funcs)<1000{panic("incomplete function coverage")};bad:=[]string{};maintained:=0;other:=map[string]bool{};for _,fn:=range t.Funcs{if strings.Contains(fn.Name,"golang.org/x/crypto/openpgp"){bad=append(bad,fn.Name)};if strings.Contains(fn.Name,"github.com/ProtonMail/go-crypto/openpgp"){maintained++};if strings.Contains(fn.Name,"golang.org/x/crypto/"){n:=strings.Split(strings.SplitN(fn.Name,"golang.org/x/crypto/",2)[1],".")[0];other[n]=true}};bi,e:=buildinfo.ReadFile(p);if e!=nil{panic(e)};r,_:=os.Open(p);defer r.Close();h:=sha256.New();io.Copy(h,r);out:=map[string]any{"sha256":hex.EncodeToString(h.Sum(nil)),"go_version":bi.GoVersion,"parsed_function_count":len(t.Funcs),"unmaintained_openpgp_functions":bad,"maintained_protonmail_openpgp_functions":maintained,"other_x_crypto_packages":other,"not_a_raw_zero_scan_claim":true};d,_:=json.MarshalIndent(out,"","  ");fmt.Println(string(d))}
